mapper.select:
SELECT id, chapter_id, content_code, content, order_index FROM edu.ccct_items WHERE chapter_id IN
#{chapterId}
ORDER BY chapter_id, order_index

mapper.update:
UPDATE edu.ccct_profiles
SET status = 'PUBLISHED',
    published_at = #{publishedAt},
    version = version + 1,
    updated_at = NOW()
WHERE course_id = #{courseId}
  AND id = #{profileId}
  AND status = 'DRAFT'
  AND version = #{expectedVersion}
